import java.util.*;

class Solution {
    public boolean canCross(int[] stones) {
        int n = stones.length;
        // Map stone position to its index for quick lookup
        Map<Integer, Integer> stoneIndices = new HashMap<>();
        for (int i = 0; i < n; i++) {
            stoneIndices.put(stones[i], i);
        }

        // dp[i] holds a set of jump lengths that can land on stone i
        Set<Integer>[] dp = new HashSet[n];
        for (int i = 0; i < n; i++) {
            dp[i] = new HashSet<>();
        }
        dp[0].add(0); // starting point, no jump made yet

        for (int i = 0; i < n; i++) {
            for (int k : dp[i]) {
                // next jumps can be k-1, k, or k+1 units
                for (int step = k - 1; step <= k + 1; step++) {
                    if (step > 0) {
                        int nextPos = stones[i] + step;
                        if (stoneIndices.containsKey(nextPos)) {
                            int nextIndex = stoneIndices.get(nextPos);
                            dp[nextIndex].add(step);
                        }
                    }
                }
            }
        }

        return !dp[n - 1].isEmpty();
    }
}

